def compute_reward(context):
    base_reward = float(context['base_reward'])
    terminated = bool(context['terminated'])
    truncated = bool(context['truncated'])
    terminal_bonus = 0.25 if terminated and not truncated and base_reward > 0.0 else 0.0
    time_penalty = -0.01 / max(1.0, float(context['episode_limit']))
    subreward_dict = {
        'base_reward_term': base_reward,
        'terminal_bonus': terminal_bonus,
        'time_penalty': time_penalty,
    }
    return {
        'team_reward': sum(subreward_dict.values()),
        'subreward_dict': subreward_dict,
        'aux_stats': {
            'base_reward': base_reward,
            'terminated': 1.0 if terminated else 0.0,
            'truncated': 1.0 if truncated else 0.0,
        },
    }
